mapper.select:
select s.id as id, s.account_id as account_id, s.name as name, s.code as code, s.refresh_interval as refresh_interval, s.schedule_type as schedule_type, s.schedule_time as schedule_time, s.schedule_cron as schedule_cron, s.alert_audio_path as alert_audio_path, s.is_enabled as is_enabled, s.created_at as created_at, s.updated_at as updated_at, a.label as account_label, a.username as account_username, w.name as website_name, w.url as website_url, coalesce(w.login_type, '') as login_type, w.category as category from website_schedules s join accounts a on a.id = s.account_id join websites w on w.id = a.website_id
and (a.label like concat('%', #{keyword}, '%') or a.username like concat('%', #{keyword}, '%')) and s.schedule_type = #{scheduleType}
order by s.updated_at desc
